/**
 * 内置天空盒（等距全景）：台球厅。
 *
 * 来源：Billiard Hall by Greg Zaal (photography) / Jarod Guest (processing), Poly Haven, CC0。
 * https://polyhaven.com/a/billiard_hall
 *
 * 以 512×256、64 色调色板 + 6 位索引存储（前 192 字节是调色板，后面是 4 个索引打包进 3 字节），
 * 共约 96KB，base64 后约 131KB。桌面端与小程序都不需要图片解码、资源路径或网络加载，
 * 运行时直接展开成 DataTexture，两端的天空盒完全同源。
 */
export const SKYBOX_WIDTH = 512
export const SKYBOX_HEIGHT = 256
export const SKYBOX_PALETTE_SIZE = 64
export const SKYBOX_DATA_BASE64 =
  ""
